def dump(cfg, mask=False):
    for k in sorted(cfg):
        v = cfg[k]
        if mask and any(s in k for s in ("pass", "token", "secret", "key")):
            v = "***"
        print(f"  {k}={v}")

print("naive startup dump:")
dump(config)
print("masked startup dump:")
dump(config, mask=True)

def validate(cfg, env):
    if env == "production" and cfg["password"] in ("CHANGEME", "password", ""):
        return "REJECTED: placeholder password in production"
    if cfg["password"] in ("CHANGEME", "password", ""):
        return "warning: placeholder password (allowed outside production)"
    return "ok"

cfg = {"password": "CHANGEME"}
print("development:", validate(cfg, "development"))
print("production: ", validate(cfg, "production"))

